const d = $input.first().json;
const SC = d.SCREENING;
const all = d.results || [];

function hasKW(text, keywords) {
  const t = (text||'').toLowerCase();
  for (const k of keywords) { if (t.includes(k.toLowerCase())) return true; }
  return false;
}

function isExcluded(title, abstract) {
  const t = (title||'').toLowerCase();
  const a = (abstract||'').toLowerCase();
  for (const ex of (SC.exclude_if_title||[])) { if (t.includes(ex)) return true; }
  for (const ex of (SC.exclude_if||[])) { if (t.includes(ex) || a.includes(ex)) return true; }
  return false;
}

const results = all.map(art => {
  const title = art.title || '';
  const abstract = art.abstract || '';
  const text = title + ' ' + abstract;

  // Check exclusions first
  if (isExcluded(title, abstract)) {
    return {...art, q1_ad:'NO', q2_speech:'NO', q3_ai:'NO', decision:'EXCLUDE', reason:'Excluded by title/abstract keywords'};
  }

  // 3 binary questions
  const q1 = hasKW(text, SC.ad_keywords);
  const q2 = hasKW(text, SC.speech_keywords);
  const q3 = hasKW(text, SC.ai_keywords);
  const yesCount = (q1?1:0) + (q2?1:0) + (q3?1:0);

  let decision, tier='';
  if (yesCount === 3) { decision = 'INCLUDE'; }
  else if (yesCount === 2) { decision = 'BORDERLINE'; tier = 'A'; }
  else if (yesCount === 1) { decision = 'BORDERLINE'; tier = 'B'; }
  else { decision = 'EXCLUDE'; }

  return {
    ...art,
    q1_ad: q1 ? 'YES' : 'NO',
    q2_speech: q2 ? 'YES' : 'NO', 
    q3_ai: q3 ? 'YES' : 'NO',
    decision,
    borderline_tier: tier,
    filter_auto: yesCount === 3 ? 'INCLUDE' : yesCount === 2 ? 'BORDERLINE-A' : yesCount === 1 ? 'BORDERLINE-B' : 'EXCLUDE',
  };
});

const inc = results.filter(r => r.decision === 'INCLUDE').length;
const bordA = results.filter(r => r.filter_auto === 'BORDERLINE-A').length;
const bordB = results.filter(r => r.filter_auto === 'BORDERLINE-B').length;
const exc = results.filter(r => r.decision === 'EXCLUDE').length;

return [{json:{
  ...d,
  results,
  screening: { total: results.length, include: inc, borderline_a: bordA, borderline_b: bordB, exclude: exc },
}}];

