// Robust tag extractor — handles multiline, attributes, nested tags
function safeExtract(block, tag) {
  const patterns = [
    new RegExp('<'+tag+'[^>]*>([\\s\\S]*?)</'+tag+'>', 'i'),
    new RegExp('<'+tag+'>([\\s\\S]*?)</'+tag+'>', 'i'),
  ];
  for (const p of patterns) {
    const m = block.match(p);
    if (m) return m[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  }
  return '';
}

