    let enriched=0;
    for(const batch of batches){
      const doiFilter=batch.map(a=>a.doi).join('|');
      const url='https://api.openalex.org/works?filter=doi:'+encodeURIComponent(doiFilter)+'&select=doi,cited_by_count&per_page=50&mailto='+(K.email||'');
      try{
        const r=await this.helpers.httpRequest({method:'GET',url,timeout:15000});
        if(r?.results){
          const citMap={};
          for(const w of r.results)if(w.doi)citMap[w.doi.replace('https://doi.org/','').toLowerCase()]=w.cited_by_count||0;
          for(const a of batch){
            const c=citMap[a.doi]||0;
            if(c>0){a.citations=c;enriched++;}
          }
        }
      }catch(e){warnings.push('[WARN] Springer citation enrich batch failed: '+e.message.slice(0,50));}
    }
    if(enriched>0)warnings.push('[INFO] '+enriched+'/'+springerNoCit.length+' Springer articles got citation data');
  }catch(e){warnings.push('[WARN] Springer citation enrichment failed: '+e.message.slice(0,50));}
}

const{source_result,...cleanBase}=base;
return [{json:{...cleanBase,
  articles:allArticles, api_status:apiStatus, api_timings:apiTimings,
  api_details:apiDetails, search_archive:searchArchive, warnings,
  merge:{total:allArticles.length,ok,failed:6-ok,sources_received:items.length},
  layer3_stats:{
    total_records:allArticles.length, sources_ok:ok,
    avg_completeness:allArticles.length>0?Math.round(allArticles.reduce((s,a)=>s+a.metadata_completeness,0)/allArticles.length):0,
    records_with_abstract:allArticles.filter(a=>!a.no_abstract).length,
    records_with_doi:allArticles.filter(a=>a.doi&&a.doi.length>3).length,
    springer_citations_enriched:allArticles.filter(a=>a.source==='Springer'&&a.citations>0).length,
  },
}}];

// ══════════════════════════════════════════════════════════════════
// 🔍 DEDUP v16 — SEPARATED MODULE
// D1: Fuzzy Jaccard trigram
// D2: Fallback Author+Year+words
// D3: Preprint/published merge
// Produces: clean dedup_audit_log
// ══════════════════════════════════════════════════════════════════
const d=$input.first().json;
const articles=d.articles||[];

function trigramSet(text){
  const t=text.toLowerCase().replace(/[^a-z0-9 ]/g,'');
  const words=t.split(/\s+/);
  const tris=new Set();
  for(const w of words)for(let i=0;i<=w.length-3;i++)tris.add(w.slice(i,i+3));
  return tris;
}
function jaccard(s1,s2){
  if(!s1.size||!s2.size)return 0;
  const inter=[...s1].filter(x=>s2.has(x)).length;
  return inter/(s1.size+s2.size-inter);
}
function firstAuthorLast(au){
  if(!au)return '';
  const first=au.split(';')[0].split(',')[0].trim();
  const parts=first.split(' ');
  return parts[parts.length-1].toLowerCase();
}
function normTitle(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'').slice(0,80);}

const seenDOI=new Map(), seenTitle=new Map();
const seenTrigrams=[];
const unique=[];let dups=0;const dupLog=[];
const dedupMethods={DOI_EXACT:0,TITLE_EXACT:0,FUZZY:0,AUTHOR_YEAR_WORDS:0};

for(const a of articles){
  const dk=a.doi&&a.doi.length>3?a.doi.toLowerCase().trim():null;
  const tk=normTitle(a.title);
  if(!tk||tk.length<10){dups++;continue;}
  let isDup=false,dupMethod='',dupOf='';

  // Level 1: DOI exact
  if(dk&&seenDOI.has(dk)){isDup=true;dupMethod='DOI_EXACT';dupOf=seenDOI.get(dk);}

  // Level 2: Title exact
  if(!isDup&&seenTitle.has(tk)){isDup=true;dupMethod='TITLE_EXACT';dupOf=seenTitle.get(tk);}

  // Level 3: Fuzzy Jaccard + author confirm
  if(!isDup&&a.title){
    const artTri=trigramSet(a.title);
    const artAuth=firstAuthorLast(a.authors||'');
    const artYear=a.year;
    for(const[prevTri,prevSrc,prevAuth,prevYear]of seenTrigrams){
      const sim=jaccard(artTri,prevTri);
      if(sim>=0.85){
        if(artAuth&&prevAuth&&artAuth===prevAuth&&artYear===prevYear){
          isDup=true;dupMethod=`FUZZY(${sim.toFixed(2)})+AUTHOR`;dupOf=prevSrc;break;
        } else if(sim>=0.95){
          isDup=true;dupMethod=`FUZZY(${sim.toFixed(2)})`;dupOf=prevSrc;break;
        }
      }
    }
  }

  // Level 4: Author+Year+first3words
  if(!isDup&&a.title&&a.authors&&a.year){
    const artA=firstAuthorLast(a.authors);
    const artW=a.title.toLowerCase().replace(/[^a-z0-9 ]/g,'').split(' ').slice(0,3).join('_');
    const key4=`${artA}_${a.year}_${artW}`;
    for(const prev of unique){
      const prevA=firstAuthorLast(prev.authors||'');
      const prevW=(prev.title||'').toLowerCase().replace(/[^a-z0-9 ]/g,'').split(' ').slice(0,3).join('_');
      const prevKey4=`${prevA}_${prev.year}_${prevW}`;
      if(key4===prevKey4&&key4.length>10){isDup=true;dupMethod='AUTHOR_YEAR_WORDS';dupOf=prev.source;break;}
    }
  }

  if(isDup){
    dups++;
    const baseMethod=dupMethod.split('(')[0].replace('+AUTHOR','');
    if(baseMethod.startsWith('FUZZY'))dedupMethods.FUZZY++;
    else dedupMethods[baseMethod]=(dedupMethods[baseMethod]||0)+1;
    dupLog.push({
      record_id: a.record_id,
      title:(a.title||'').slice(0,80),
      source:a.source,
      dup_of:dupOf,
      method:dupMethod,
      timestamp: d.timestamp_utc,
    });
  } else {
    if(dk)seenDOI.set(dk,a.source);
    seenTitle.set(tk,a.source);
    if(a.title)seenTrigrams.push([trigramSet(a.title),a.source,firstAuthorLast(a.authors||''),a.year]);
    unique.push(a);
  }
}

return [{json:{...d,
  articles: unique,
  dedup_removed: dups,
  dedup_unique: unique.length,
  dedup_methods: dedupMethods,
  dedup_audit_log: dupLog,
  layer4_stats: {
    input: articles.length,
    duplicates: dups,
    unique: unique.length,
    dedup_rate: articles.length>0?Math.round((dups/articles.length)*100)+'%':'0%',
    methods: dedupMethods,
  },
}}];

// ════════════════════════════════════════════════════════════════════
// 📊 Format for Google Sheets — domain-agnostic version
// ════════════════════════════════════════════════════════════════════
// Reads everything from upstream Config (no hardcoded keywords).
// The keyword lists used here come from c.SCREENING:
//   - SCREENING.ad_keywords     (= POPULATION group from Config)
//   - SCREENING.speech_keywords (= INTERVENTION group)
//   - SCREENING.ai_keywords     (= METHOD group)
// ════════════════════════════════════════════════════════════════════

const d = $input.first().json;
const all = d.results || [];

// Read keyword lists from upstream Config (single source of truth)
const SCREENING = d.screening_config || d.SCREENING || {};
const AD = SCREENING.ad_keywords     || SCREENING.population_keywords   || [];
const SP = SCREENING.speech_keywords || SCREENING.intervention_keywords || [];
const AI = SCREENING.ai_keywords     || SCREENING.method_keywords       || [];

if (!AD.length || !SP.length || !AI.length) {
  throw new Error('Format node: missing keyword lists in upstream config. Verify Screening node passes SCREENING with population/intervention/method keyword arrays.');
}

// Sort: INCLUDE first, then BORDERLINE-A, BORDERLINE-B, EXCLUDE; then by score
const sorted = [...all].sort((a, b) => {
  const order = { 'INCLUDE': 0, 'BORDERLINE-A': 1, 'BORDERLINE-B': 2, 'EXCLUDE': 3 };
  const oa = order[a.decision] ?? 4, ob = order[b.decision] ?? 4;
  if (oa !== ob) return oa - ob;
  return (b.score || 0) - (a.score || 0);
});

// Decode HTML entities + strip tags (cleans up abstract HTML noise)
function dec(s) {
  return (s || '')
    .replace(/&#x([0-9a-f]+);/gi, (_, c) => String.fromCharCode(parseInt(c, 16)))
    .replace(/&#(\d+);/g,         (_, c) => String.fromCharCode(c))
    .replace(/&amp;/g,  '&').replace(/&lt;/g,   '<').replace(/&gt;/g,  '>')
    .replace(/&apos;/g, "'").replace(/&quot;/g, '"')
    .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

// Case-insensitive substring match against a keyword list
function hasKW(text, kw) {
  const t = (text || '').toLowerCase();
  for (const k of kw) {
    if (k && t.includes(String(k).toLowerCase())) return true;
  }
  return false;
}

return sorted.map(a => {
  const title    = dec(a.title || '');
  const abstract = dec(a.abstract || '');
  const jName    = a.journal_name || a.journal || a.venue || '';

  // Re-derive q1/q2/q3 from upstream keyword lists (consistent with Layer 1)
  // If Screening node already populated these on the record, use them directly:
  const q1 = (a.q1_population !== undefined) ? a.q1_population
           : (hasKW(title, AD) || hasKW(abstract, AD));
  const q2 = (a.q2_intervention !== undefined) ? a.q2_intervention
           : (hasKW(title, SP) || hasKW(abstract, SP));
  const q3 = (a.q3_method !== undefined) ? a.q3_method
           : (hasKW(title, AI) || hasKW(abstract, AI));

  // Decision: 3=INCLUDE, 2=BORDERLINE-A, 1=BORDERLINE-B, 0=EXCLUDE
  const yes = (q1 ? 1 : 0) + (q2 ? 1 : 0) + (q3 ? 1 : 0);
  let fa;
  if      (yes === 3) fa = 'INCLUDE';
  else if (yes === 2) fa = 'BORDERLINE-A';
  else if (yes === 1) fa = 'BORDERLINE-B';
  else                fa = 'EXCLUDE';

  return {
    json: {
      title:               title.slice(0, 300),
      authors:             (a.authors || '').slice(0, 250),
      year:                a.year || '',
      doi:                 a.doi || '',
      venue_name:          jName,
      source:              a.source || '',
      publication_type:    '',
      venue_quality:       '',
      q1_ad:               q1 ? 'YES' : 'NO',
      q2_speech:           q2 ? 'YES' : 'NO',
      q3_ai:               q3 ? 'YES' : 'NO',
      filter_auto:         fa,
      filter_llm:          '',
      raison_llm:          '',
      filter_manuel:       '',
      raison_manuelle:     '',
      filter_pdf:          '',
      filter_readfulltext: '',
      raison_readfulltext: '',
      citations:           a.citations    || 0,
      cit_per_year:        a.cit_per_year || 0,
      is_multimodal:       a.is_multimodal ? 'YES' : '',
      is_oa:               a.is_oa         ? 'YES' : '',
      abstract:            (abstract || '').slice(0, 600),
      pdf_status:          '',
      drive_link:          '',
    }
  };
});

const items = $input.all();
return [{json: {
  status: 'DONE',
  rows: items.length,
  message: items.length + ' articles written to ARTICLES_SCREENED. Run WF2 next.',
}}];
